    "code": "   8  def rand_pose(\n   9      xlim: np.ndarray,\n  10      ylim: np.ndarray,\n  11      zlim: np.ndarray = [0.741],\n  12      ylim_prop=False,\n  13      rotate_rand=False,\n  14      rotate_lim=[0, 0, 0],\n  15      qpos=[1, 0, 0, 0],\n  16  ) -> sapien.Pose:\n  17      if len(xlim) < 2 or xlim[1] < xlim[0]:\n  18          xlim = np.array([xlim[0], xlim[0]])\n  19      if len(ylim) < 2 or ylim[1] < ylim[0]:\n  20          ylim = np.array([ylim[0], ylim[0]])\n  21      if len(zlim) < 2 or zlim[1] < zlim[0]:\n  22          zlim = np.array([zlim[0], zlim[0]])\n  23  \n  24      x = np.random.uniform(xlim[0], xlim[1])\n  25      y = np.random.uniform(ylim[0], ylim[1])\n  26  \n  27      while ylim_prop and abs(x) < 0.15 and y > 0:\n  28          y = np.random.uniform(ylim[0], 0)\n  29  \n  30      z = np.random.uniform(zlim[0], zlim[1])\n  31  \n  32      rotate = qpos\n  33      if rotate_rand:\n  34          angles = [0, 0, 0]\n  35          for i in range(3):\n  36              angles[i] = np.random.uniform(-rotate_lim[i], rotate_lim[i])\n  37          rotate_quat = t3d.euler.euler2quat(angles[0], angles[1], angles[2])\n  38          rotate = t3d.quaternions.qmult(rotate, rotate_quat)\n  39  \n  40      return sapien.Pose([x, y, z], rotate)",
